      "content": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\"\n    xmlns:tools=\"http://schemas.android.com/tools\">\n\n    <!-- Audio capture for on-device whisper.cpp & hands-free \"Mangal\" wake word -->\n    <uses-permission android:name=\"android.permission.RECORD_AUDIO\" />\n    <uses-permission android:name=\"android.permission.FOREGROUND_SERVICE\" />\n    <uses-permission android:name=\"android.permission.FOREGROUND_SERVICE_MICROPHONE\" />\n    <uses-permission android:name=\"android.permission.POST_NOTIFICATIONS\" />\n\n    <!-- Initial Wi-Fi model download ONLY; unused during 100% offline runtime inference -->\n    <uses-permission android:name=\"android.permission.INTERNET\" />\n    <uses-permission android:name=\"android.permission.ACCESS_NETWORK_STATE\" />\n\n    <!--\n      PLAY PROTECT COMPLIANCE NOTE:\n      We intentionally omit restricted SEND_SMS, CALL_PHONE, and SCHEDULE_EXACT_ALARM\n      permissions that trigger Google Play Protect \"Harmful App / Toll Fraud\" warnings on\n      non-default handlers. Instead, SMS, calls, and alarms use verified system intents\n      (ACTION_SENDTO smsto:, ACTION_DIAL tel:, and SET_ALARM) or optional CalendarContract.\n    -->\n    <uses-permission android:name=\"com.android.alarm.permission.SET_ALARM\" />\n    <uses-permission android:name=\"android.permission.READ_CALENDAR\" />\n    <uses-permission android:name=\"android.permission.WRITE_CALENDAR\" />\n    <uses-permission android:name=\"android.permission.READ_CONTACTS\" />\n\n    <!-- Hardware feature declarations (non-blocking for Wi-Fi tablets without telephony/flash) -->\n    <uses-feature android:name=\"android.hardware.telephony\" android:required=\"false\" />\n    <uses-feature android:name=\"android.hardware.camera.flash\" android:required=\"false\" />\n    <uses-feature android:name=\"android.hardware.microphone\" android:required=\"true\" />\n\n    <!-- Package visibility for opening apps, alarms, SMS/Dialer, and search on Android 11+ (API 30+) -->\n    <queries>\n        <intent>\n            <action android:name=\"android.intent.action.MAIN\" />\n            <category android:name=\"android.intent.category.LAUNCHER\" />\n        </intent>\n        <intent>\n            <action android:name=\"android.intent.action.SET_ALARM\" />\n        </intent>\n        <intent>\n            <action android:name=\"android.intent.action.SET_TIMER\" />\n        </intent>\n        <intent>\n            <action android:name=\"android.intent.action.SENDTO\" />\n            <data android:scheme=\"smsto\" />\n        </intent>\n        <intent>\n            <action android:name=\"android.intent.action.DIAL\" />\n            <data android:scheme=\"tel\" />\n        </intent>\n        <intent>\n            <action android:name=\"android.intent.action.WEB_SEARCH\" />\n        </intent>\n    </queries>\n\n    <application\n        android:name=\".MangalApplication\"\n        android:icon=\"@mipmap/ic_launcher\"\n        android:roundIcon=\"@mipmap/ic_launcher_round\"\n        android:allowBackup=\"false\"\n        android:fullBackupContent=\"false\"\n        android:dataExtractionRules=\"@xml/data_extraction_rules\"\n        android:networkSecurityConfig=\"@xml/network_security_config\"\n        android:usesCleartextTraffic=\"false\"\n        android:label=\"MANGAL\"\n        android:supportsRtl=\"true\"\n        android:theme=\"@android:style/Theme.Material.NoActionBar\"\n        tools:targetApi=\"35\">\n\n        <activity\n            android:name=\".MainActivity\"\n            android:exported=\"true\"\n            android:windowSoftInputMode=\"adjustResize\">\n            <intent-filter>\n                <action android:name=\"android.intent.action.MAIN\" />\n                <category android:name=\"android.intent.category.LAUNCHER\" />\n                <!-- Supports Android Digital Assistant long-press home gesture -->\n                <action android:name=\"android.intent.action.ASSIST\" />\n                <category android:name=\"android.intent.category.DEFAULT\" />\n            </intent-filter>\n        </activity>\n\n        <!-- Hands-Free \"Mangal\" Wake Word Service with explicit microphone foregroundServiceType -->\n        <service\n            android:name=\".service.MangalWakeWordForegroundService\"\n            android:exported=\"false\"\n            android:foregroundServiceType=\"microphone\" />\n    </application>\n</manifest>\n"
